import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_plugin_lib_lang_typecheck","description":"","frontmatter":{},"headers":[],"relativePath":"api/lib-lang-typecheck/handl_plugin_lib_lang_typecheck/index.md","filePath":"api/lib-lang-typecheck/handl_plugin_lib_lang_typecheck/index.md"}`),a={name:`api/lib-lang-typecheck/handl_plugin_lib_lang_typecheck/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-plugin-lib-lang-typecheck" tabindex="-1">handl_plugin_lib_lang_typecheck <a class="header-anchor" href="#handl-plugin-lib-lang-typecheck" aria-label="Permalink to “handl_plugin_lib_lang_typecheck”">​</a></h1><h1 id="handl-plugin-lib-lang-typecheck-1" tabindex="-1">handl-plugin-lib-lang-typecheck <a class="header-anchor" href="#handl-plugin-lib-lang-typecheck-1" aria-label="Permalink to “handl-plugin-lib-lang-typecheck”">​</a></h1><p>The <code>typecheck</code> meta function as a composable <code>plugin-lib-*</code> leaf crate (ADR-0054 §6, ADR-0047 §1).</p><p>Exposes the <code>typecheck</code> module with one callable: <code>typecheck.typecheck(lang, ast)</code>. It extracts the [<code>handl_language::Language</code>] from the first argument, accepts the second argument as either a tagged <code>__ast__</code> value or a raw JSON-serialized [<code>handl_language::Ast</code>], builds a sub-runtime via [<code>handl_runtime::RuntimeFactory</code>], typechecks the AST, and returns the synthesized type (a value — types are values, ADR-0032).</p><p>This is the <strong>pure-eval</strong> path (ADR-0054 §&quot;The typecheck host is pure&quot;): type expressions are evaluated via the bound typecheck engine without running effects. The CLI&#39;s <code>typecheck</code> command calls this.</p><p>This crate is a leaf: it depends on <code>handl-runtime</code> (the abstraction + <code>RuntimeFactory</code>/<code>RuntimeHandle</code> traits), <code>handl-language</code>, and <code>handl-platform</code>/<code>handl-plugin-module</code> only — no engine impl crates, no <code>handl-kit-*</code>.</p><h2 id="wiring-note" tabindex="-1">Wiring note <a class="header-anchor" href="#wiring-note" aria-label="Permalink to “Wiring note”">​</a></h2><p>The meta modules hold an [<code>Rc&lt;dyn RuntimeFactory&gt;</code>] which is not <code>Send + Sync</code>, so the [<code>LangTypecheckLibraryPlugin</code>] cannot contribute its module through <a href="./handl_plugin_module::ModuleRuntime.html"><code>ModuleRuntime</code></a>. The host wires the [<code>TypecheckModule</code>] directly via <a href="./handl_runtime::RuntimeFactory::build.html"><code>RuntimeFactory::build</code></a>&#39;s <code>delegate</code> parameter. See [<code>LangTypecheckLibraryPlugin</code>].</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-plugin-lib-lang-typecheck-2" tabindex="-1"><a href="./handl_plugin_lib_lang_typecheck.html"><code>handl_plugin_lib_lang_typecheck</code></a> <a class="header-anchor" href="#handl-plugin-lib-lang-typecheck-2" aria-label="Permalink to “handl_plugin_lib_lang_typecheck”">​</a></h3><p><em>1 constant, 1 function, 3 structs</em></p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};